-- Verbatim structural baseline from MIGRATION_SQL before the P0/P1 pass.
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agent_installations (id TEXT PRIMARY KEY, agent_type TEXT NOT NULL, path TEXT NOT NULL, detected_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, agent_type TEXT NOT NULL, title TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, working_directory TEXT, git_repository TEXT, source_path TEXT NOT NULL, detail_json TEXT NOT NULL, parse_warning TEXT);
CREATE TABLE IF NOT EXISTS session_messages (id TEXT PRIMARY KEY, session_id TEXT NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL, timestamp TEXT, FOREIGN KEY(session_id) REFERENCES sessions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS session_tool_calls (id TEXT PRIMARY KEY, session_id TEXT NOT NULL, name TEXT NOT NULL, arguments TEXT NOT NULL, status TEXT NOT NULL, output TEXT, timestamp TEXT, FOREIGN KEY(session_id) REFERENCES sessions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS packages (id TEXT PRIMARY KEY, title TEXT NOT NULL, source_agent TEXT NOT NULL, target_agent TEXT NOT NULL, created_at TEXT NOT NULL, project_path TEXT, package_path TEXT NOT NULL, schema_version TEXT NOT NULL, integrity TEXT NOT NULL, has_patch INTEGER NOT NULL, security_warning_count INTEGER NOT NULL, imported INTEGER NOT NULL, resumed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS package_files (package_id TEXT NOT NULL, relative_path TEXT NOT NULL, sha256 TEXT NOT NULL, size INTEGER NOT NULL, PRIMARY KEY(package_id, relative_path), FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS scan_jobs (id TEXT PRIMARY KEY, started_at TEXT NOT NULL, completed_at TEXT, status TEXT NOT NULL, discovered_count INTEGER NOT NULL DEFAULT 0, error TEXT);
CREATE TABLE IF NOT EXISTS security_findings (id INTEGER PRIMARY KEY AUTOINCREMENT, package_id TEXT NOT NULL, finding_type TEXT NOT NULL, source_file TEXT NOT NULL, field_path TEXT NOT NULL, severity TEXT NOT NULL, FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_sessions_updated ON sessions(updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_packages_created ON packages(created_at DESC);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, project_path TEXT NOT NULL, git_repository TEXT, goal TEXT NOT NULL, constraints_json TEXT NOT NULL, default_agent TEXT NOT NULL, default_model TEXT NOT NULL, current_branch_id TEXT NOT NULL, current_task TEXT NOT NULL DEFAULT '', archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversation_branches (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, name TEXT NOT NULL, parent_branch_id TEXT, fork_node_id TEXT, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS conversation_nodes (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, parent_node_id TEXT, branch_id TEXT NOT NULL, source_agent TEXT, source_session_id TEXT, node_type TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL, importance INTEGER NOT NULL DEFAULT 50, status TEXT NOT NULL DEFAULT 'active', metadata_json TEXT NOT NULL DEFAULT '{}', FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, FOREIGN KEY(branch_id) REFERENCES conversation_branches(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS source_sessions (id TEXT PRIMARY KEY, agent_type TEXT NOT NULL, title TEXT NOT NULL, source_path TEXT NOT NULL, working_directory TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, detail_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_messages (id TEXT PRIMARY KEY, source_session_id TEXT NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT, raw_index INTEGER NOT NULL, FOREIGN KEY(source_session_id) REFERENCES source_sessions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tool_calls_v2 (id TEXT PRIMARY KEY, source_session_id TEXT NOT NULL, name TEXT NOT NULL, arguments TEXT NOT NULL, status TEXT NOT NULL, output TEXT, created_at TEXT, FOREIGN KEY(source_session_id) REFERENCES source_sessions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS file_changes (id TEXT PRIMARY KEY, source_session_id TEXT NOT NULL, path TEXT NOT NULL, change_type TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(source_session_id) REFERENCES source_sessions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS project_bindings (project_id TEXT NOT NULL, binding_type TEXT NOT NULL, binding_id TEXT NOT NULL, branch_id TEXT, created_at TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', PRIMARY KEY(project_id,binding_type,binding_id), FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS context_snapshots (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, branch_id TEXT NOT NULL, source_node_id TEXT, target_agent TEXT NOT NULL, target_model TEXT NOT NULL, token_budget INTEGER NOT NULL, estimated_tokens INTEGER NOT NULL, compiled_context TEXT NOT NULL, compiled_json TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS context_items (id TEXT PRIMARY KEY, snapshot_id TEXT NOT NULL, source_node_id TEXT, category TEXT NOT NULL, action TEXT NOT NULL, reason TEXT NOT NULL, estimated_tokens INTEGER NOT NULL, content TEXT NOT NULL, pinned INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(snapshot_id) REFERENCES context_snapshots(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS continuations (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, branch_id TEXT NOT NULL, source_node_id TEXT, snapshot_id TEXT NOT NULL, target_agent TEXT NOT NULL, target_model TEXT NOT NULL, mode TEXT NOT NULL, status TEXT NOT NULL, bootstrap_file TEXT NOT NULL, launch_command TEXT NOT NULL, target_session_id TEXT, created_at TEXT NOT NULL, warning TEXT, process_id INTEGER, working_directory TEXT NOT NULL DEFAULT '', context_hash TEXT NOT NULL DEFAULT '', marker TEXT NOT NULL DEFAULT '', started_at TEXT NOT NULL DEFAULT '', detected_at TEXT, listening INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS agent_capabilities (agent_type TEXT PRIMARY KEY, capabilities_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS skills (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL, source_platform TEXT NOT NULL, source_path TEXT NOT NULL, compatible_agents_json TEXT NOT NULL, required_tools_json TEXT NOT NULL, instructions TEXT NOT NULL, installation_state TEXT NOT NULL, discovered_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mcp_servers (id TEXT PRIMARY KEY, name TEXT NOT NULL, source_agent TEXT NOT NULL, command TEXT, transport TEXT NOT NULL, compatible_agents_json TEXT NOT NULL, discovered_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_nodes_project_branch ON conversation_nodes(project_id,branch_id,created_at);
CREATE INDEX IF NOT EXISTS idx_nodes_source_session ON conversation_nodes(source_session_id);
CREATE INDEX IF NOT EXISTS idx_bindings_project ON project_bindings(project_id,binding_type);
CREATE INDEX IF NOT EXISTS idx_snapshots_project ON context_snapshots(project_id,created_at DESC);
